# build map pkg->funcs
python3 - <<'EOF'
import os,re,subprocess,collections
root='/bench/home/work'
decls=[]  # (pkgpath, pkgname, func, file, line)
for dirpath,dirs,files in os.walk(os.path.join(root,'internal')):
    for fn in files:
        if not fn.endswith('.go') or fn.endswith('_test.go'): continue
        p=os.path.join(dirpath,fn)
        src=open(p, encoding='utf8', errors='ignore').read()
        m=re.search(r'^package (\w+)',src,re.M)
        pkg=m.group(1) if m else '?'
        for i,line in enumerate(src.split('\n'),1):
            mm=re.match(r'func ([A-Z]\w*)\(',line)
            if mm: decls.append((pkg,mm.group(1),os.path.relpath(p,root),i))
            mm2=re.match(r'func \([^)]*\) ([A-Z]\w*)\(',line)
            if mm2: decls.append((pkg+'.M',mm2.group(1),os.path.relpath(p,root),i))
# count usages
allgo=[]
for dirpath,dirs,files in os.walk(root):
    if '/.git' in dirpath or '/web' in dirpath or 'graphify-out' in dirpath: continue
    for fn in files:
        if fn.endswith('.go'):
            allgo.append(os.path.join(dirpath,fn))
texts={p:open(p,encoding='utf8',errors='ignore').read() for p in allgo}
res=[]
for pkg,fname,file,line in decls:
    if pkg.endswith('.M'):
        pat=re.compile(r'\.'+fname+r'\(')
    else:
        pat=re.compile(r'\b'+pkg+r'\.'+fname+r'\(')
    n=0; nprod=0
    for p,t in texts.items():
        if os.path.relpath(p,root)==file: 
            c=len(pat.findall(t))-1
        else:
            c=len(pat.findall(t))
        if c>0:
            n+=c
            if not p.endswith('_test.go'): nprod+=c
    res.append((nprod,n,pkg,fname,file,line))
res.sort(reverse=True)
for r in res[:30]:
    print(r)
EOF

